cd /workspace && PYTHONPATH=/workspace/skills/tau2Retail/src node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// Execute the exchange by updating the order directly
const order = db.prepare(\"SELECT * FROM orders WHERE order_id='#W7231611'\").get();

if (order.status !== 'delivered') {
  console.log('ERROR: Order is not in delivered status');
  process.exit(1);
}

// Update order status and exchange fields
db.prepare(\`
  UPDATE orders SET
    status = 'exchange requested',
    exchange_items = ?,
    exchange_new_items = ?,
    exchange_payment_method_id = ?,
    exchange_price_difference = ?
  WHERE order_id = '#W7231611'
\`).run(
  JSON.stringify(['3301828484']),
  JSON.stringify(['7389318502']),
  'credit_card_9958253',
  0.46
);

// Verify the update
console.log('=== UPDATED ORDER ===');
const updated = db.prepare(\"SELECT order_id, status, exchange_items, exchange_new_items, exchange_payment_method_id, exchange_price_difference FROM orders WHERE order_id='#W7231611'\").get();
console.log(JSON.stringify(updated, null, 2));

console.log('\nExchange processed successfully!');
"
